// ── Value (primitive) vs Reference (object) ─────────────────────

// Primitives: assignment copies the VALUE
let a = 10;
let b = a;   // b gets an independent copy
b = 99;
console.log(a); // 10 — unchanged

// Objects: assignment copies the REFERENCE
const user1 = { name: 'Alice', score: 42 };
const user2 = user1; // same heap address
user2.score = 100;
console.log(user1.score); // 100 — same object!

// Shallow clone breaks the top-level alias…
const user3 = { ...user1 };
user3.score = 0;
console.log(user1.score); // 100 — user3 is a new object

// …but nested objects are STILL shared
const order = { id: 1, address: { city: 'Tokyo' } };
const clone = { ...order };
clone.address.city = 'Osaka';
console.log(order.address.city); // 'Osaka' — shared reference!

// Deep clone to fully decouple
const deep = structuredClone(order);
deep.address.city = 'Kyoto';
console.log(order.address.city); // 'Osaka' — independent now

// ── const does NOT freeze heap data ─────────────────────────────
const arr = [1, 2, 3];
arr.push(4);      // OK — mutates the heap array
console.log(arr); // [1, 2, 3, 4]
// arr = [];      // TypeError — cannot reassign the reference

// Use Object.freeze() to lock own properties (shallow)
const cfg = Object.freeze({ host: 'localhost', port: 3000 });
cfg.port = 9999;  // silently ignored (strict mode throws)
console.log(cfg.port); // 3000

// Stack frame lifecycle
function add(x, y) {
  // x, y live on the stack for this call only
  const sum = x + y; // sum also on the stack
  return sum;
  // frame popped — x, y, sum gone
}
console.log(add(3, 4)); // 7
